set -e
cd /home/admin1/projects/webhook-gateway
docker compose exec -T api node - <<'JS'
const {Client}=require('pg');
(async()=>{
 const client=new Client({connectionString:process.env.DATABASE_URL});
 await client.connect();
 try {
  const q=await client.query(
   'SELECT e.provider_event_id,d.destination_id,d.status,d.attempt_count,d.last_status_code,(d.delivered_at IS NOT NULL) AS delivered,o.status AS outbox_status FROM events e JOIN deliveries d ON d.event_id=e.id LEFT JOIN delivery_outbox o ON o.delivery_id=d.id WHERE e.provider_event_id=$1 AND e.source_id=$2',
   ['req_52ac76d410b2e8a99fa630c5','server-core-github']
  );
  console.log(JSON.stringify({count:q.rowCount,deliveries:q.rows}));
  if(q.rowCount!==1 || q.rows[0].status!=='delivered'||q.rows[0].delivered!==true)process.exitCode=2;
 }finally{await client.end();}
})().catch(e=>{console.log('DB_QUERY_FAILED',e.code||e.message);process.exitCode=3});
JS
